('general', 1, 'Quel est le nom du petit déjeuner anglais traditionnel avec œufs et bacon ?', 'English breakfast', ARRAY['Brunch', 'Continental breakfast', 'High tea'], 'fr', true, 'L''English breakfast comprend des œufs, du bacon, des saucisses, des haricots et du toast.'),
('general', 1, 'Quel est le nom du gaz qui fait flotter les ballons de fête ?', 'L''hélium', ARRAY['L''hydrogène', 'L''azote', 'L''oxygène'], 'fr', true, 'L''hélium est un gaz plus léger que l''air, ce qui permet aux ballons de flotter.'),
('general', 1, 'Quel oiseau est le symbole des États-Unis ?', 'L''aigle chauve', ARRAY['Le faucon', 'Le condor', 'Le hibou'], 'fr', true, 'L''aigle à tête blanche, ou pygargue, est l''emblème national des États-Unis depuis 1782.'),
('general', 1, 'Quel est le nom du célèbre peintre des tournesols ?', 'Vincent van Gogh', ARRAY['Claude Monet', 'Pablo Picasso', 'Salvador Dalí'], 'fr', true, 'Van Gogh a peint sa célèbre série des Tournesols en 1888 à Arles, en France.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('general', 2, 'Quel pays a inventé la pizza ?', 'L''Italie', ARRAY['Les États-Unis', 'La Grèce', 'La France'], 'fr', true, 'La pizza moderne est née à Naples, en Italie, au XVIIIe siècle.'),
