('general', 3, 'Quelle est la plus petite particule d''un élément chimique ?', 'L''atome', ARRAY['La molécule', 'L''électron', 'Le proton'], 'fr', true, 'L''atome est la plus petite unité d''un élément chimique qui conserve ses propriétés.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('general', 4, 'Quel est le nom du paradoxe quantique impliquant un chat dans une boîte ?', 'Le chat de Schrödinger', ARRAY['Le paradoxe d''Einstein', 'Le principe de Heisenberg', 'Le paradoxe de Fermi'], 'fr', true, 'Le chat de Schrödinger illustre le principe de superposition en mécanique quantique.'),
