('general', 4, 'Quel est le nom de la plus grande fleur du monde ?', 'La rafflésie', ARRAY['Le tournesol', 'Le nénuphar géant', 'L''arum titan'], 'fr', true, 'La rafflesia arnoldii peut mesurer jusqu''à 1 mètre de diamètre et peser 11 kg.'),
('general', 4, 'Quel est le nom du phénomène où un son semble changer de fréquence lorsque la source se déplace ?', 'L''effet Doppler', ARRAY['L''effet Venturi', 'L''effet Bernoulli', 'L''effet Coriolis'], 'fr', true, 'L''effet Doppler explique pourquoi le son d''une ambulance change quand elle passe devant nous.'),
('general', 4, 'Quel est le seul mammifère capable de voler véritablement ?', 'La chauve-souris', ARRAY['L''écureuil volant', 'Le colugo', 'Le sugar glider'], 'fr', true, 'Les chauves-souris sont les seuls mammifères capables de vol actif et soutenu.'),
('general', 4, 'Quel est le nom du processus de transformation d''un gaz en liquide ?', 'La condensation', ARRAY['L''évaporation', 'La sublimation', 'La fusion'], 'fr', true, 'La condensation est le passage de l''état gazeux à l''état liquide par refroidissement.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('general', 5, 'Quel est le nom de la constante physique notée « c » ?', 'La vitesse de la lumière', ARRAY['La constante de Planck', 'La constante gravitationnelle', 'La constante de Boltzmann'], 'fr', true, 'La lettre c désigne la vitesse de la lumière dans le vide, soit 299 792 458 m/s exactement.'),
