('general', 5, 'Quel est le métal le plus dense à température ambiante ?', 'L''osmium', ARRAY['Le platine', 'L''iridium', 'Le tungstène'], 'fr', true, 'L''osmium a une densité de 22,59 g/cm³, ce qui en fait le métal le plus dense.'),
('general', 5, 'Quel est le nom du plus long mot de la langue française dans un dictionnaire courant ?', 'Anticonstitutionnellement', ARRAY['Électroencéphalographie', 'Intergouvernementalisations', 'Hippopotomonstrosesquipédaliophobie'], 'fr', true, 'Anticonstitutionnellement, avec 25 lettres, est traditionnellement considéré comme le plus long mot français.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
