('general', 1, 'What is the traditional English breakfast called?', 'Full English', ARRAY['Brunch', 'Continental', 'High tea'], 'en', true, 'A Full English breakfast includes eggs, bacon, sausages, beans, and toast.'),
('general', 1, 'What instrument measures weight?', 'A scale', ARRAY['A thermometer', 'A barometer', 'A stopwatch'], 'en', true, 'A scale measures mass by comparing an object to reference weights.'),
('general', 1, 'What is the color of the sun when viewed from space?', 'White', ARRAY['Yellow', 'Orange', 'Red'], 'en', true, 'The sun emits white light, but Earth''s atmosphere gives it a yellowish tint.'),
