('general', 1, 'How many legs does an insect have?', '6', ARRAY['4', '8', '10'], 'en', true, 'All insects have exactly 6 legs, distinguishing them from arachnids which have 8.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('general', 2, 'Which country invented pizza?', 'Italy', ARRAY['United States', 'Greece', 'France'], 'en', true, 'Modern pizza originated in Naples, Italy in the 18th century.'),
