('general', 2, 'What is the currency of the United Kingdom?', 'British pound sterling', ARRAY['Euro', 'Dollar', 'Franc'], 'en', true, 'The pound sterling is the oldest currency still in use in the world.'),
('general', 2, 'Who developed the theory of relativity?', 'Albert Einstein', ARRAY['Isaac Newton', 'Stephen Hawking', 'Niels Bohr'], 'en', true, 'Einstein published special relativity in 1905 and general relativity in 1915.'),
('general', 2, 'What is the longest river in Africa?', 'The Nile', ARRAY['The Congo', 'The Niger', 'The Zambezi'], 'en', true, 'The Nile is about 6,650 km long and flows through 11 African countries.'),
('general', 2, 'What is the alphabet used in Russia called?', 'Cyrillic', ARRAY['Greek', 'Latin', 'Arabic'], 'en', true, 'The Cyrillic alphabet is used in Russia and several other Slavic countries.'),
