('general', 2, 'How many baby teeth does a child have?', '20', ARRAY['16', '24', '28'], 'en', true, 'Children have 20 baby teeth that fall out between ages 6 and 12.'),
('general', 2, 'What famous painting shows a woman with a mysterious smile?', 'The Mona Lisa', ARRAY['The Starry Night', 'The Scream', 'Girl with a Pearl Earring'], 'en', true, 'The Mona Lisa was painted by Leonardo da Vinci and hangs in the Louvre in Paris.'),
('general', 2, 'What is the chemical symbol for sodium?', 'Na', ARRAY['So', 'Sd', 'No'], 'en', true, 'Na comes from the Latin word natrium, meaning sodium.'),
('general', 2, 'How many vertebrae does the human spine have?', '33', ARRAY['26', '30', '36'], 'en', true, 'The human spine has 33 vertebrae divided into 5 regions.'),
