INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('general', 3, 'What is the chemical formula for table salt?', 'NaCl', ARRAY['KCl', 'CaCO3', 'NaOH'], 'en', true, 'NaCl is sodium chloride, composed of one sodium atom and one chlorine atom.'),
