('general', 3, 'What is the name of the first artificial satellite launched in 1957?', 'Sputnik', ARRAY['Explorer', 'Vanguard', 'Luna'], 'en', true, 'Sputnik 1 was launched by the USSR on October 4, 1957.'),
('general', 3, 'Who discovered radioactivity?', 'Henri Becquerel', ARRAY['Marie Curie', 'Pierre Curie', 'Ernest Rutherford'], 'en', true, 'Henri Becquerel discovered radioactivity in 1896 while studying uranium salts.'),
('general', 3, 'How many bones does an adult human have?', '206', ARRAY['186', '212', '256'], 'en', true, 'The adult human skeleton is composed of 206 bones.'),
