('general', 3, 'What is the oldest university in the world still in operation?', 'University of Bologna', ARRAY['Oxford', 'Sorbonne', 'Cambridge'], 'en', true, 'The University of Bologna in Italy was founded in 1088.'),
('general', 3, 'Who was the first person to walk on the Moon?', 'Neil Armstrong', ARRAY['Buzz Aldrin', 'Yuri Gagarin', 'John Glenn'], 'en', true, 'Neil Armstrong walked on the Moon on July 20, 1969, during the Apollo 11 mission.'),
('general', 3, 'What liquid metal was used in traditional thermometers?', 'Mercury', ARRAY['Lead', 'Silver', 'Tin'], 'en', true, 'Mercury is the only metal that is liquid at room temperature.'),
('general', 3, 'What is the tallest person ever recorded?', '2.72 m (8 ft 11 in)', ARRAY['2.50 m', '2.85 m', '2.60 m'], 'en', true, 'Robert Wadlow measured 2.72 m, the tallest person in recorded history.'),
('general', 3, 'Which country consumes the most coffee per capita?', 'Finland', ARRAY['Brazil', 'United States', 'Italy'], 'en', true, 'Finns consume about 12 kg of coffee per person per year.'),
('general', 3, 'What is the name of the theory explaining the origin of the universe?', 'The Big Bang', ARRAY['String theory', 'Relativity', 'Steady state'], 'en', true, 'The Big Bang theory states that the universe formed about 13.8 billion years ago.'),
