INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('general', 4, 'What is the name of the quantum paradox involving a cat in a box?', 'Schrodinger''s cat', ARRAY['Einstein''s paradox', 'Heisenberg''s principle', 'Fermi''s paradox'], 'en', true, 'Schrodinger''s cat illustrates the principle of superposition in quantum mechanics.'),
('general', 4, 'What law states that computing power doubles approximately every 18 months?', 'Moore''s Law', ARRAY['Murphy''s Law', 'Pareto''s Law', 'Metcalfe''s Law'], 'en', true, 'Gordon Moore formulated this observation in 1965 about transistor density.'),
('general', 4, 'What is the first book printed by Gutenberg?', 'The Bible', ARRAY['The Iliad', 'The Quran', 'The Divine Comedy'], 'en', true, 'The Gutenberg Bible, printed around 1455, was the first book printed with movable type.'),
('general', 4, 'What is the name of the rare atmospheric phenomenon that appears as a luminous ball?', 'Ball lightning', ARRAY['Heat lightning', 'St. Elmo''s fire', 'Sprites'], 'en', true, 'Ball lightning is a rare and poorly understood phenomenon observed for centuries.'),
('general', 4, 'How many liters of water can a camel drink in one go?', 'About 100 liters', ARRAY['30 liters', '50 liters', '200 liters'], 'en', true, 'A thirsty camel can drink up to 100 liters of water in just 10 minutes.'),
('general', 4, 'What is the name of the world''s largest flower?', 'Rafflesia', ARRAY['Sunflower', 'Giant water lily', 'Titan arum'], 'en', true, 'Rafflesia arnoldii can measure up to 1 meter in diameter and weigh 11 kg.'),
('general', 4, 'What is the Doppler effect?', 'A change in wave frequency due to relative motion', ARRAY['A visual illusion', 'A magnetic phenomenon', 'A gravitational wave'], 'en', true, 'The Doppler effect explains why an ambulance siren changes pitch as it passes by.'),
('general', 4, 'What is the only mammal truly capable of flight?', 'The bat', ARRAY['The flying squirrel', 'The colugo', 'The sugar glider'], 'en', true, 'Bats are the only mammals capable of sustained, active flight.'),
('general', 4, 'What is the process of a gas turning into a liquid called?', 'Condensation', ARRAY['Evaporation', 'Sublimation', 'Fusion'], 'en', true, 'Condensation is the transition from the gaseous to the liquid state through cooling.'),
('general', 4, 'What is Avogadro''s number (approximately)?', '6.022 x 10^23', ARRAY['3.14 x 10^23', '9.8 x 10^23', '1.38 x 10^23'], 'en', true, 'Avogadro''s number is 6.022 x 10^23, the number of entities in one mole.'),
('general', 4, 'Which organ consumes the most energy relative to its size?', 'The brain', ARRAY['The heart', 'The liver', 'The kidneys'], 'en', true, 'The brain is only 2% of body weight but consumes 20% of the body''s energy.'),
('general', 4, 'What is the name of the oldest desert in the world?', 'The Namib', ARRAY['The Sahara', 'The Atacama', 'The Gobi'], 'en', true, 'The Namib Desert in southern Africa has existed for about 55 to 80 million years.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('general', 5, 'What physical constant is denoted by the letter "c"?', 'The speed of light', ARRAY['Planck''s constant', 'Gravitational constant', 'Boltzmann constant'], 'en', true, 'The letter c denotes the speed of light in a vacuum, exactly 299,792,458 m/s.'),
('general', 5, 'What is the densest metal at room temperature?', 'Osmium', ARRAY['Platinum', 'Iridium', 'Tungsten'], 'en', true, 'Osmium has a density of 22.59 g/cm3, making it the densest metal.'),
('general', 5, 'What is the name of the point of infinite density in a black hole?', 'Singularity', ARRAY['Event horizon', 'Ergosphere', 'Lagrange point'], 'en', true, 'The singularity is the central point of a black hole where spacetime curvature becomes infinite.'),
('general', 5, 'What is the fastest chemical reaction known?', 'Photoisomerization of rhodopsin', ARRAY['Combustion of hydrogen', 'Nuclear fission', 'Acid-base neutralization'], 'en', true, 'Rhodopsin photoisomerization in the eye occurs in about 200 femtoseconds.'),
('general', 5, 'What is the Chandrasekhar limit?', 'The maximum mass of a white dwarf star', ARRAY['The minimum mass of a black hole', 'The orbital speed limit', 'The temperature limit of a star'], 'en', true, 'The Chandrasekhar limit is about 1.4 solar masses, beyond which a white dwarf collapses.'),
('general', 5, 'What is the rarest blood type in the world?', 'AB negative', ARRAY['O negative', 'B negative', 'A negative'], 'en', true, 'AB negative is found in less than 1% of the world''s population.'),
('general', 5, 'What is the name of the hypothetical boundary around a star within which planets could have liquid water?', 'The habitable zone', ARRAY['The Oort cloud', 'The Kuiper belt', 'The heliosphere'], 'en', true, 'The habitable zone, also called the Goldilocks zone, is where conditions may support liquid water.'),
('general', 5, 'What is the most distant man-made object from Earth?', 'Voyager 1', ARRAY['Voyager 2', 'New Horizons', 'Pioneer 10'], 'en', true, 'Voyager 1, launched in 1977, is now over 24 billion km from Earth in interstellar space.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 1, 'Quel empire a construit le Machu Picchu au Pérou ?', 'L''Empire inca', ARRAY['L''Empire aztèque', 'L''Empire maya', 'L''Empire espagnol'], 'fr', true, 'Le Machu Picchu a été construit par les Incas au XVe siècle dans les Andes péruviennes.'),
('history', 1, 'Qui a été le premier président des États-Unis ?', 'George Washington', ARRAY['Abraham Lincoln', 'Thomas Jefferson', 'Benjamin Franklin'], 'fr', true, 'George Washington a été le premier président des États-Unis de 1789 à 1797.'),
('history', 1, 'Quel événement a eu lieu le 6 juin 1944 ?', 'Le débarquement en Normandie', ARRAY['La libération de Paris', 'La capitulation allemande', 'La bataille de Stalingrad'], 'fr', true, 'Le Jour J, le 6 juin 1944, les Alliés ont débarqué sur les plages de Normandie.'),
('history', 1, 'Quel pays a construit le canal de Suez ?', 'La France', ARRAY['L''Angleterre', 'L''Égypte', 'L''Empire ottoman'], 'fr', true, 'Le canal de Suez a été construit par la France sous la direction de Ferdinand de Lesseps, ouvert en 1869.'),
('history', 1, 'Quel roi de France a régné le plus longtemps ?', 'Louis XIV', ARRAY['Louis XVI', 'Charlemagne', 'François Ier'], 'fr', true, 'Louis XIV a régné pendant 72 ans (1643-1715), le plus long règne de l''histoire de France.'),
('history', 1, 'Quel est le nom du mur qui divisait Berlin en deux ?', 'Le mur de Berlin', ARRAY['Le rideau de fer', 'La ligne Maginot', 'Le mur d''Hadrien'], 'fr', true, 'Le mur de Berlin a séparé Berlin-Ouest de Berlin-Est de 1961 à 1989.'),
('history', 1, 'Quelle civilisation a inventé le papier ?', 'La Chine', ARRAY['L''Égypte', 'La Grèce', 'Rome'], 'fr', true, 'Le papier a été inventé en Chine vers 105 apr. J.-C. par Cai Lun.'),
('history', 1, 'Quel continent a été découvert par les Européens en 1492 ?', 'L''Amérique', ARRAY['L''Australie', 'L''Antarctique', 'L''Afrique'], 'fr', true, 'Christophe Colomb a atteint les Amériques en 1492 en cherchant une route vers les Indes.'),
('history', 1, 'Qui a peint La Joconde ?', 'Léonard de Vinci', ARRAY['Michel-Ange', 'Raphaël', 'Botticelli'], 'fr', true, 'Léonard de Vinci a peint La Joconde (Mona Lisa) vers 1503-1519 à Florence.'),
('history', 1, 'Quel pharaon est célèbre pour son masque funéraire en or ?', 'Toutânkhamon', ARRAY['Ramsès II', 'Khéops', 'Akhenaton'], 'fr', true, 'Le masque funéraire de Toutânkhamon, en or massif, a été découvert par Howard Carter en 1922.'),
('history', 1, 'Quel était le nom du navire de Christophe Colomb ?', 'La Santa María', ARRAY['Le Mayflower', 'La Pinta', 'Le Victoria'], 'fr', true, 'La Santa María était le navire amiral de Christophe Colomb lors de son premier voyage en 1492.'),
('history', 1, 'Quel personnage historique a dit « Veni, vidi, vici » ?', 'Jules César', ARRAY['Auguste', 'Alexandre le Grand', 'Napoléon'], 'fr', true, 'Jules César a prononcé cette phrase (« Je suis venu, j''ai vu, j''ai vaincu ») après sa victoire à Zéla en 47 av. J.-C.'),
('history', 1, 'Quel peuple a construit les premières pyramides d''Égypte ?', 'Les Égyptiens', ARRAY['Les Romains', 'Les Grecs', 'Les Perses'], 'fr', true, 'Les premières pyramides égyptiennes datent d''environ 2700 av. J.-C., sous l''Ancien Empire.'),
('history', 1, 'Quelle guerre a opposé le Nord et le Sud des États-Unis ?', 'La guerre de Sécession', ARRAY['La guerre d''Indépendance', 'La guerre de 1812', 'La guerre hispano-américaine'], 'fr', true, 'La guerre de Sécession (1861-1865) a opposé les États de l''Union au Nord aux Confédérés au Sud.'),
('history', 1, 'Quel explorateur a fait le premier tour du monde ?', 'Magellan', ARRAY['Christophe Colomb', 'Vasco de Gama', 'James Cook'], 'fr', true, 'Ferdinand de Magellan a lancé la première circumnavigation en 1519, achevée par Elcano en 1522.'),
('history', 1, 'Quel monument a été construit pour l''Exposition universelle de 1889 à Paris ?', 'La Tour Eiffel', ARRAY['L''Arc de Triomphe', 'Le Grand Palais', 'Le Trocadéro'], 'fr', true, 'La Tour Eiffel, conçue par Gustave Eiffel, a été inaugurée pour l''Exposition universelle de 1889.'),
('history', 1, 'Quel empire dominait le bassin méditerranéen il y a 2000 ans ?', 'L''Empire romain', ARRAY['L''Empire grec', 'L''Empire perse', 'L''Empire carthaginois'], 'fr', true, 'L''Empire romain dominait tout le pourtour méditerranéen à son apogée au IIe siècle.'),
('history', 1, 'Quel navigateur portugais a donné son nom au détroit entre l''Amérique du Sud et la Terre de Feu ?', 'Magellan', ARRAY['Vasco de Gama', 'Bartolomeu Dias', 'Pedro Cabral'], 'fr', true, 'Le détroit de Magellan a été traversé par Fernand de Magellan en 1520.'),
('history', 1, 'Quelle invention a permis de communiquer à distance au XIXe siècle ?', 'Le télégraphe', ARRAY['Le téléphone', 'La radio', 'La télévision'], 'fr', true, 'Le télégraphe électrique, développé par Samuel Morse dans les années 1830, a révolutionné les communications.'),
('history', 1, 'Quel est le nom du bateau qui a transporté les premiers colons anglais en Amérique en 1620 ?', 'Le Mayflower', ARRAY['La Santa María', 'Le Titanic', 'Le Victoria'], 'fr', true, 'Le Mayflower a transporté les Pères pèlerins de Plymouth en Angleterre vers l''Amérique en 1620.'),
('history', 1, 'Quelle civilisation antique a inventé l''écriture cunéiforme ?', 'Les Sumériens', ARRAY['Les Égyptiens', 'Les Grecs', 'Les Chinois'], 'fr', true, 'Les Sumériens de Mésopotamie ont développé l''écriture cunéiforme vers 3400 av. J.-C.'),
('history', 1, 'Quel roi anglais a eu six épouses ?', 'Henri VIII', ARRAY['Henri V', 'Richard Cœur de Lion', 'Édouard Ier'], 'fr', true, 'Henri VIII d''Angleterre a eu six épouses et a fondé l''Église anglicane pour obtenir l''annulation de son premier mariage.'),
('history', 1, 'Quel événement a marqué la fin de la Seconde Guerre mondiale dans le Pacifique ?', 'Les bombes atomiques sur Hiroshima et Nagasaki', ARRAY['La bataille de Midway', 'La capitulation de l''Allemagne', 'Le débarquement en Normandie'], 'fr', true, 'Les bombes atomiques larguées en août 1945 ont conduit à la capitulation du Japon.'),
('history', 1, 'Quel peuple d''Asie centrale a fondé le plus grand empire continental de l''histoire ?', 'Les Mongols', ARRAY['Les Turcs', 'Les Perses', 'Les Huns'], 'fr', true, 'L''Empire mongol, fondé par Gengis Khan, s''étendait de la Chine à l''Europe de l''Est.'),
('history', 1, 'Quel célèbre discours commence par « I have a dream » ?', 'Le discours de Martin Luther King', ARRAY['Le discours de Kennedy', 'Le discours de Lincoln', 'Le discours de Mandela'], 'fr', true, 'Martin Luther King a prononcé ce discours le 28 août 1963 à Washington pour les droits civiques.'),
('history', 1, 'Quel est le nom de la première constitution écrite au monde ?', 'La Constitution américaine', ARRAY['La Magna Carta', 'La Déclaration des droits de l''homme', 'Le Code de Hammurabi'], 'fr', true, 'La Constitution des États-Unis, ratifiée en 1788, est la plus ancienne constitution écrite encore en vigueur.'),
('history', 1, 'Quel scientifique a formulé la loi de la gravitation universelle ?', 'Isaac Newton', ARRAY['Galilée', 'Albert Einstein', 'Copernic'], 'fr', true, 'Newton a publié sa loi de la gravitation universelle dans les Principia en 1687.'),
('history', 1, 'Quel pays européen a colonisé l''Inde pendant plusieurs siècles ?', 'Le Royaume-Uni', ARRAY['La France', 'Le Portugal', 'L''Espagne'], 'fr', true, 'L''Inde a été sous domination britannique de 1858 à 1947.'),
('history', 1, 'Quel monument de pierre se trouve dans la plaine de Salisbury en Angleterre ?', 'Stonehenge', ARRAY['Le Colisée', 'Le Parthénon', 'Les menhirs de Carnac'], 'fr', true, 'Stonehenge est un monument mégalithique construit entre 3000 et 2000 av. J.-C.'),
('history', 1, 'Quel était le titre des dirigeants de l''Égypte antique ?', 'Pharaon', ARRAY['Empereur', 'Roi', 'Sultan'], 'fr', true, 'Le pharaon était considéré comme un dieu vivant dans l''Égypte ancienne.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 2, 'En quelle année a eu lieu la Révolution russe ?', '1917', ARRAY['1905', '1914', '1921'], 'fr', true, 'La Révolution russe de 1917 a renversé le tsar Nicolas II et porté les bolcheviks au pouvoir.'),
('history', 2, 'Quel empire a été le plus vaste de l''histoire ?', 'L''Empire britannique', ARRAY['L''Empire mongol', 'L''Empire romain', 'L''Empire espagnol'], 'fr', true, 'L''Empire britannique couvrait environ 35 millions de km2 à son apogée dans les années 1920.'),
('history', 2, 'Quel traité a mis fin à la guerre de Trente Ans ?', 'Le traité de Westphalie', ARRAY['Le traité de Versailles', 'Le traité de Paris', 'Le traité de Vienne'], 'fr', true, 'Les traités de Westphalie en 1648 ont mis fin à la guerre de Trente Ans et redessiné l''Europe.'),
('history', 2, 'Quel empereur romain a construit le mur en Angleterre ?', 'Hadrien', ARRAY['Trajan', 'Auguste', 'Néron'], 'fr', true, 'Le mur d''Hadrien, construit en 122 apr. J.-C., marquait la frontière nord de l''Empire romain en Bretagne.'),
('history', 2, 'Quel événement a précipité l''entrée des États-Unis dans la Seconde Guerre mondiale ?', 'L''attaque de Pearl Harbor', ARRAY['Le blitz de Londres', 'La bataille de Stalingrad', 'L''invasion de la Pologne'], 'fr', true, 'L''attaque japonaise sur Pearl Harbor le 7 décembre 1941 a provoqué l''entrée en guerre des États-Unis.'),
('history', 2, 'Quel mouvement artistique et intellectuel est né en Italie au XIVe siècle ?', 'La Renaissance', ARRAY['Le Baroque', 'Les Lumières', 'Le Romantisme'], 'fr', true, 'La Renaissance est née à Florence au XIVe siècle avec des artistes comme Giotto et Brunelleschi.'),
('history', 2, 'Quelle reine d''Angleterre a régné pendant 63 ans au XIXe siècle ?', 'Victoria', ARRAY['Élisabeth Ire', 'Marie Stuart', 'Anne'], 'fr', true, 'La reine Victoria a régné de 1837 à 1901, donnant son nom à l''ère victorienne.'),
('history', 2, 'Quel est le nom de la bataille décisive qui a mis fin à l''expansion napoléonienne en Russie ?', 'La retraite de Russie', ARRAY['Austerlitz', 'Waterloo', 'Trafalgar'], 'fr', true, 'La campagne de Russie de 1812 s''est soldée par une retraite catastrophique de la Grande Armée.'),
('history', 2, 'Quel pays asiatique est resté fermé aux étrangers pendant plus de 200 ans ?', 'Le Japon', ARRAY['La Chine', 'La Corée', 'Le Vietnam'], 'fr', true, 'Le Japon a pratiqué le sakoku (pays fermé) de 1639 à 1853 sous le shogunat Tokugawa.'),
('history', 2, 'Quel est le nom de la doctrine américaine interdisant l''ingérence européenne en Amérique ?', 'La doctrine Monroe', ARRAY['La doctrine Truman', 'Le New Deal', 'Le plan Marshall'], 'fr', true, 'La doctrine Monroe, proclamée en 1823, affirmait que l''Amérique n''était plus ouverte à la colonisation européenne.'),
('history', 2, 'Quel empire a régné sur la Perse avant la conquête d''Alexandre le Grand ?', 'L''Empire achéménide', ARRAY['L''Empire sassanide', 'L''Empire parthe', 'L''Empire séleucide'], 'fr', true, 'L''Empire achéménide, fondé par Cyrus le Grand, a dominé la Perse de 550 à 330 av. J.-C.'),
('history', 2, 'En quelle année Nelson Mandela a-t-il été libéré de prison ?', '1990', ARRAY['1988', '1994', '1985'], 'fr', true, 'Nelson Mandela a été libéré le 11 février 1990 après 27 ans de détention.'),
('history', 2, 'Quel est le nom de la guerre entre les maisons York et Lancaster en Angleterre ?', 'La guerre des Roses', ARRAY['La guerre de Cent Ans', 'La guerre civile anglaise', 'La guerre des Deux-Roses'], 'fr', true, 'La guerre des Roses (1455-1487) a opposé les maisons York (rose blanche) et Lancaster (rose rouge).'),
('history', 2, 'Quel leader a mené la révolution cubaine en 1959 ?', 'Fidel Castro', ARRAY['Che Guevara', 'Raúl Castro', 'Fulgencio Batista'], 'fr', true, 'Fidel Castro a renversé le dictateur Batista et pris le pouvoir à Cuba en janvier 1959.'),
('history', 2, 'Quelle civilisation a construit la cité de Machu Picchu ?', 'Les Incas', ARRAY['Les Aztèques', 'Les Mayas', 'Les Olmèques'], 'fr', true, 'Le Machu Picchu a été construit par les Incas au XVe siècle à 2 430 m d''altitude au Pérou.'),
('history', 2, 'Quel accord a créé l''Union européenne en 1992 ?', 'Le traité de Maastricht', ARRAY['Le traité de Rome', 'Le traité de Lisbonne', 'Le traité de Nice'], 'fr', true, 'Le traité de Maastricht, signé en 1992, a créé l''Union européenne et préparé l''euro.'),
('history', 2, 'Quel est le nom de la première mission spatiale habitée à atterrir sur la Lune ?', 'Apollo 11', ARRAY['Apollo 13', 'Gemini 4', 'Vostok 1'], 'fr', true, 'Apollo 11 a posé Neil Armstrong et Buzz Aldrin sur la Lune le 20 juillet 1969.'),
('history', 2, 'Quel pays a été le dernier à abolir l''esclavage en 1888 ?', 'Le Brésil', ARRAY['Les États-Unis', 'Cuba', 'Haïti'], 'fr', true, 'Le Brésil a été le dernier pays des Amériques à abolir l''esclavage avec la Loi d''or en 1888.'),
('history', 2, 'Quel conflit a opposé les États-Unis et l''URSS de 1947 à 1991 ?', 'La guerre froide', ARRAY['La guerre du Vietnam', 'La guerre de Corée', 'La course aux armements'], 'fr', true, 'La guerre froide était un conflit géopolitique et idéologique sans affrontement militaire direct.'),
('history', 2, 'Quel empire africain était célèbre pour sa richesse en or au XIVe siècle ?', 'L''Empire du Mali', ARRAY['L''Empire songhaï', 'Le Royaume du Bénin', 'Le Royaume du Ghana'], 'fr', true, 'L''empereur Mansa Moussa du Mali était considéré comme l''homme le plus riche de l''histoire.'),
('history', 2, 'Quel est le nom de la ligne fortifiée construite par la France entre les deux guerres ?', 'La ligne Maginot', ARRAY['La ligne Siegfried', 'Le mur de l''Atlantique', 'La ligne Hindenburg'], 'fr', true, 'La ligne Maginot, construite dans les années 1930, devait protéger la France d''une invasion allemande.'),
('history', 2, 'En quelle année l''Inde a-t-elle obtenu son indépendance ?', '1947', ARRAY['1945', '1950', '1942'], 'fr', true, 'L''Inde a obtenu son indépendance du Royaume-Uni le 15 août 1947 sous la direction de Gandhi et Nehru.'),
('history', 2, 'Quel est le nom du premier empereur de Chine qui a unifié le pays ?', 'Qin Shi Huang', ARRAY['Confucius', 'Sun Tzu', 'Kublai Khan'], 'fr', true, 'Qin Shi Huang a unifié la Chine en 221 av. J.-C. et commencé la Grande Muraille.'),
('history', 2, 'Quelle organisation internationale a été créée après la Seconde Guerre mondiale pour maintenir la paix ?', 'L''ONU', ARRAY['L''OTAN', 'La Société des Nations', 'L''UNESCO'], 'fr', true, 'L''Organisation des Nations Unies a été fondée en 1945 avec 51 pays membres.'),
('history', 2, 'Quel est le nom du programme spatial qui a envoyé le premier homme dans l''espace ?', 'Vostok', ARRAY['Mercury', 'Apollo', 'Gemini'], 'fr', true, 'Le programme Vostok a envoyé Youri Gagarine dans l''espace le 12 avril 1961.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 3, 'Quel est le nom du programme américain qui a développé la bombe atomique ?', 'Le projet Manhattan', ARRAY['Le projet Apollo', 'Le plan Marshall', 'L''opération Overlord'], 'fr', true, 'Le projet Manhattan a développé les premières armes nucléaires entre 1942 et 1946.'),
('history', 3, 'Quelle bataille de 1916 est la plus meurtrière de la Première Guerre mondiale ?', 'La bataille de la Somme', ARRAY['La bataille de Verdun', 'La bataille de la Marne', 'La bataille de Gallipoli'], 'fr', true, 'La bataille de la Somme a causé plus d''un million de victimes entre juillet et novembre 1916.'),
('history', 3, 'Quel est le nom du premier cosmonaute à effectuer une sortie dans l''espace ?', 'Alexeï Leonov', ARRAY['Youri Gagarine', 'Neil Armstrong', 'Valentina Terechkova'], 'fr', true, 'Alexeï Leonov a effectué la première sortie extravéhiculaire le 18 mars 1965.'),
('history', 3, 'Quel empereur romain a divisé l''empire en deux parties ?', 'Dioclétien', ARRAY['Constantin', 'Théodose', 'Auguste'], 'fr', true, 'Dioclétien a instauré la tétrarchie en 293, divisant l''administration de l''Empire romain.'),
('history', 3, 'Quelle conférence de 1945 a redessiné les frontières de l''Europe après la guerre ?', 'La conférence de Yalta', ARRAY['La conférence de Potsdam', 'La conférence de Téhéran', 'La conférence de Casablanca'], 'fr', true, 'La conférence de Yalta en février 1945 a réuni Roosevelt, Churchill et Staline.'),
('history', 3, 'Quel mouvement social et politique a émergé dans les années 1960 aux États-Unis pour les droits civiques ?', 'Le mouvement des droits civiques', ARRAY['Le mouvement hippie', 'Le mouvement ouvrier', 'Le mouvement féministe'], 'fr', true, 'Le mouvement des droits civiques a lutté contre la ségrégation raciale aux États-Unis dans les années 1950-1960.'),
('history', 3, 'Quel pays a lancé la première sonde spatiale à se poser sur Mars ?', 'L''URSS', ARRAY['Les États-Unis', 'L''Europe', 'La Chine'], 'fr', true, 'La sonde soviétique Mars 3 a été la première à se poser en douceur sur Mars en 1971.'),
('history', 3, 'Quel siège a duré 872 jours pendant la Seconde Guerre mondiale ?', 'Le siège de Leningrad', ARRAY['Le siège de Stalingrad', 'Le siège de Berlin', 'Le siège de Varsovie'], 'fr', true, 'Le siège de Leningrad par les forces allemandes a duré du 8 septembre 1941 au 27 janvier 1944.'),
('history', 3, 'Quel traité a créé la Communauté économique européenne en 1957 ?', 'Le traité de Rome', ARRAY['Le traité de Maastricht', 'Le traité de Versailles', 'Le traité de Lisbonne'], 'fr', true, 'Le traité de Rome, signé le 25 mars 1957, a fondé la CEE avec 6 pays membres.'),
('history', 3, 'Quel est le nom de la révolution iranienne de 1979 ?', 'La révolution islamique', ARRAY['La révolution blanche', 'La révolution des Œillets', 'La révolution verte'], 'fr', true, 'La révolution islamique de 1979 a renversé le Shah et instauré une république islamique sous l''ayatollah Khomeini.'),
('history', 3, 'Quel est le nom de la politique de réformes de Gorbatchev en URSS ?', 'La perestroïka', ARRAY['La glasnost', 'Le goulag', 'La détente'], 'fr', true, 'La perestroïka (restructuration) était un programme de réformes économiques et politiques lancé par Gorbatchev en 1985.'),
('history', 3, 'Quel attentat a déclenché la guerre contre le terrorisme en 2001 ?', 'Les attentats du 11 septembre', ARRAY['L''attentat de Madrid', 'L''attentat de Londres', 'L''attentat de Bali'], 'fr', true, 'Les attentats du 11 septembre 2001 à New York et Washington ont fait près de 3 000 victimes.'),
('history', 3, 'Quel empire d''Afrique de l''Ouest contrôlait le commerce transsaharien au XVe siècle ?', 'L''Empire songhaï', ARRAY['L''Empire du Mali', 'Le Royaume du Ghana', 'Le Royaume du Bénin'], 'fr', true, 'L''Empire songhaï, avec sa capitale Gao, dominait le commerce transsaharien au XVe siècle.'),
('history', 3, 'En quelle année l''apartheid a-t-il officiellement pris fin en Afrique du Sud ?', '1991', ARRAY['1990', '1994', '1988'], 'fr', true, 'Les lois de l''apartheid ont été abolies en 1991, suivies des premières élections multiraciales en 1994.'),
('history', 3, 'Quel était le nom de code de l''opération de débarquement en Normandie ?', 'Opération Overlord', ARRAY['Opération Barbarossa', 'Opération Market Garden', 'Opération Torch'], 'fr', true, 'L''opération Overlord était le nom de code du débarquement allié en Normandie le 6 juin 1944.'),
('history', 3, 'Quel scientifique a formulé les lois du mouvement des planètes ?', 'Johannes Kepler', ARRAY['Galilée', 'Copernic', 'Newton'], 'fr', true, 'Kepler a formulé ses trois lois du mouvement planétaire entre 1609 et 1619.'),
('history', 3, 'Quel pays a été le premier à accorder le droit de vote aux femmes ?', 'La Nouvelle-Zélande', ARRAY['La Finlande', 'La Norvège', 'L''Australie'], 'fr', true, 'La Nouvelle-Zélande a accordé le droit de vote aux femmes en 1893.'),
('history', 3, 'Quel est le nom de la crise qui a failli déclencher une guerre nucléaire en 1962 ?', 'La crise des missiles de Cuba', ARRAY['La crise de Berlin', 'La crise de Suez', 'La crise des otages en Iran'], 'fr', true, 'La crise des missiles de Cuba en octobre 1962 a été le moment le plus dangereux de la guerre froide.'),
('history', 3, 'Quelle dynastie chinoise a construit la majeure partie de la Grande Muraille actuelle ?', 'La dynastie Ming', ARRAY['La dynastie Qin', 'La dynastie Han', 'La dynastie Tang'], 'fr', true, 'La Grande Muraille actuelle date principalement de la dynastie Ming (1368-1644).'),
('history', 3, 'Quel pays a été le premier à industrialiser sa production textile au XVIIIe siècle ?', 'L''Angleterre', ARRAY['La France', 'L''Allemagne', 'Les États-Unis'], 'fr', true, 'L''Angleterre a été le berceau de la révolution industrielle avec ses filatures de coton.'),
('history', 3, 'Quel est le nom de la doctrine militaire allemande de guerre éclair utilisée en 1940 ?', 'Le Blitzkrieg', ARRAY['La guerre de tranchées', 'La guerre d''usure', 'La stratégie Schlieffen'], 'fr', true, 'Le Blitzkrieg (guerre éclair) combinait chars, aviation et infanterie pour des attaques rapides.'),
('history', 3, 'Quel empire a dominé l''Inde du XVIe au XIXe siècle avant les Britanniques ?', 'L''Empire moghol', ARRAY['L''Empire gupta', 'L''Empire maurya', 'L''Empire maratha'], 'fr', true, 'L''Empire moghol a régné sur une grande partie de l''Inde de 1526 à 1857, construisant le Taj Mahal.'),
('history', 3, 'Quel événement de 1989 symbolise la fin de la guerre froide ?', 'La chute du mur de Berlin', ARRAY['La dissolution de l''URSS', 'La réunification allemande', 'Les accords de Malte'], 'fr', true, 'La chute du mur de Berlin le 9 novembre 1989 est le symbole de la fin de la guerre froide.'),
('history', 3, 'Quel savant a découvert les lois de la génétique en étudiant les petits pois ?', 'Gregor Mendel', ARRAY['Charles Darwin', 'Louis Pasteur', 'Robert Koch'], 'fr', true, 'Gregor Mendel a découvert les lois de l''hérédité en étudiant les pois dans les années 1860.'),
('history', 3, 'Quel est le nom du code de lois babylonien gravé sur une stèle de pierre ?', 'Le Code de Hammurabi', ARRAY['La loi des Douze Tables', 'Le Code Justinien', 'La Magna Carta'], 'fr', true, 'Le Code de Hammurabi, datant d''environ 1754 av. J.-C., est l''un des plus anciens codes de lois écrits.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 4, 'Quel est le nom du dernier empereur de Chine ?', 'Puyi', ARRAY['Kangxi', 'Qianlong', 'Cixi'], 'fr', true, 'Puyi est devenu empereur à l''âge de 2 ans en 1908 et a abdiqué en 1912.'),
('history', 4, 'Quelle bataille navale de 1571 a stoppé l''expansion ottomane en Méditerranée ?', 'La bataille de Lépante', ARRAY['La bataille de Trafalgar', 'La bataille de Salamine', 'La bataille d''Actium'], 'fr', true, 'La bataille de Lépante en 1571 a vu la victoire de la Sainte Ligue sur la flotte ottomane.'),
('history', 4, 'Quel est le nom du premier code de lois écrit de l''histoire ?', 'Le Code d''Ur-Nammu', ARRAY['Le Code de Hammurabi', 'La loi des Douze Tables', 'Les lois de Manu'], 'fr', true, 'Le Code d''Ur-Nammu, datant d''environ 2100 av. J.-C., précède le Code de Hammurabi de 300 ans.'),
('history', 4, 'Quel traité de 1494 a partagé le Nouveau Monde entre l''Espagne et le Portugal ?', 'Le traité de Tordesillas', ARRAY['Le traité de Saragosse', 'Le traité de Westphalie', 'Le traité d''Utrecht'], 'fr', true, 'Le traité de Tordesillas a tracé une ligne de démarcation partageant les terres découvertes.'),
('history', 4, 'Quel est le nom de la révolte paysanne en Allemagne en 1524-1525 ?', 'La guerre des Paysans', ARRAY['La Jacquerie', 'La révolte des Ciompi', 'La révolte de Wat Tyler'], 'fr', true, 'La guerre des Paysans allemands a été l''un des plus grands soulèvements populaires du XVIe siècle.'),
('history', 4, 'Quel empereur byzantin a codifié le droit romain en un corpus juridique ?', 'Justinien', ARRAY['Constantin', 'Théodose', 'Héraclius'], 'fr', true, 'Le Corpus juris civilis de Justinien, compilé entre 529 et 534, est la base du droit civil moderne.'),
('history', 4, 'Quelle conférence de 1884-1885 a organisé le partage de l''Afrique entre les puissances européennes ?', 'La conférence de Berlin', ARRAY['La conférence de Vienne', 'La conférence de Paris', 'La conférence de Londres'], 'fr', true, 'La conférence de Berlin a fixé les règles de la colonisation et du partage de l''Afrique.'),
('history', 4, 'Quel est le nom de la route commerciale reliant la Chine à la Méditerranée dans l''Antiquité ?', 'La route de la Soie', ARRAY['La route des Épices', 'La route de l''Encens', 'La route de l''Ambre'], 'fr', true, 'La route de la Soie s''étendait sur plus de 6 000 km, reliant Xi''an à Constantinople.'),
('history', 4, 'Quel est le nom du plan de reconstruction de l''Europe après la Seconde Guerre mondiale ?', 'Le plan Marshall', ARRAY['Le plan Dawes', 'Le plan Schuman', 'Le plan Young'], 'fr', true, 'Le plan Marshall (1948-1952) a fourni 13 milliards de dollars d''aide américaine à l''Europe.'),
('history', 4, 'Quelle dynastie japonaise a gouverné le pays pendant l''ère Edo (1603-1868) ?', 'Les Tokugawa', ARRAY['Les Ashikaga', 'Les Fujiwara', 'Les Minamoto'], 'fr', true, 'Le shogunat Tokugawa a gouverné le Japon pendant plus de 250 ans de paix relative.'),
('history', 4, 'Quel est le nom de la réforme religieuse lancée par Martin Luther en 1517 ?', 'La Réforme protestante', ARRAY['La Contre-Réforme', 'Le Grand Schisme', 'Le concile de Trente'], 'fr', true, 'Martin Luther a lancé la Réforme en affichant ses 95 thèses à Wittenberg en 1517.'),
('history', 4, 'Quel général carthaginois a utilisé des éléphants de guerre pour traverser les Alpes ?', 'Hannibal Barca', ARRAY['Hamilcar Barca', 'Hasdrubal', 'Scipion l''Africain'], 'fr', true, 'Hannibal a traversé les Alpes avec environ 37 éléphants de guerre en 218 av. J.-C.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 5, 'Quel est le nom de la première civilisation connue de Mésopotamie ?', 'Sumer', ARRAY['Akkad', 'Babylone', 'Assyrie'], 'fr', true, 'Sumer, dans le sud de la Mésopotamie, est considérée comme la première civilisation vers 4500 av. J.-C.'),
('history', 5, 'En quelle année le traité de Nerchinsk a-t-il fixé la frontière entre la Russie et la Chine ?', '1689', ARRAY['1721', '1654', '1725'], 'fr', true, 'Le traité de Nerchinsk de 1689 a été le premier traité entre la Russie et la Chine.'),
('history', 5, 'Quel est le nom du système d''écriture utilisé par la civilisation de l''Indus ?', 'L''écriture de l''Indus', ARRAY['Le sanscrit', 'Le cunéiforme', 'Le brahmi'], 'fr', true, 'L''écriture de l''Indus reste non déchiffrée et date d''environ 2600 av. J.-C.'),
('history', 5, 'Quel amiral japonais a planifié l''attaque de Pearl Harbor ?', 'Isoroku Yamamoto', ARRAY['Hideki Tojo', 'Chuichi Nagumo', 'Takeo Kurita'], 'fr', true, 'L''amiral Yamamoto a conçu le plan d''attaque de Pearl Harbor malgré ses réserves personnelles.'),
('history', 5, 'Quel est le nom du plus ancien texte littéraire connu de l''humanité ?', 'L''Épopée de Gilgamesh', ARRAY['L''Iliade', 'La Bible', 'Le Livre des Morts'], 'fr', true, 'L''Épopée de Gilgamesh, datant d''environ 2100 av. J.-C., est le plus ancien récit littéraire connu.'),
('history', 5, 'Quel empereur moghol a fait construire le Taj Mahal ?', 'Shah Jahan', ARRAY['Akbar', 'Aurangzeb', 'Babur'], 'fr', true, 'Shah Jahan a fait construire le Taj Mahal entre 1632 et 1653 en mémoire de son épouse Mumtaz Mahal.'),
('history', 5, 'Quel est le nom du traité qui a mis fin à la guerre russo-japonaise en 1905 ?', 'Le traité de Portsmouth', ARRAY['Le traité de Shimonoseki', 'Le traité de San Stefano', 'Le traité de Brest-Litovsk'], 'fr', true, 'Le traité de Portsmouth, négocié par Theodore Roosevelt, a mis fin à la guerre russo-japonaise.'),
('history', 5, 'Quelle bataille de 1942 est considérée comme le tournant de la guerre dans le Pacifique ?', 'La bataille de Midway', ARRAY['La bataille de Guadalcanal', 'La bataille d''Iwo Jima', 'La bataille de Leyte'], 'fr', true, 'La bataille de Midway en juin 1942 a détruit 4 porte-avions japonais et inversé le cours de la guerre.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 1, 'Which empire built the Machu Picchu in Peru?', 'The Inca Empire', ARRAY['The Aztec Empire', 'The Maya Empire', 'The Spanish Empire'], 'en', true, 'Machu Picchu was built by the Incas in the 15th century in the Peruvian Andes.'),
('history', 1, 'Who was the first President of the United States?', 'George Washington', ARRAY['Abraham Lincoln', 'Thomas Jefferson', 'Benjamin Franklin'], 'en', true, 'George Washington served as the first US President from 1789 to 1797.'),
('history', 1, 'What happened on June 6, 1944?', 'D-Day invasion of Normandy', ARRAY['Liberation of Paris', 'German surrender', 'Battle of Stalingrad'], 'en', true, 'On D-Day, Allied forces landed on the beaches of Normandy, France.'),
('history', 1, 'Which king of France reigned the longest?', 'Louis XIV', ARRAY['Louis XVI', 'Charlemagne', 'Francis I'], 'en', true, 'Louis XIV reigned for 72 years (1643-1715), the longest in French history.'),
('history', 1, 'What was the name of the wall that divided Berlin?', 'The Berlin Wall', ARRAY['The Iron Curtain', 'The Maginot Line', 'Hadrian''s Wall'], 'en', true, 'The Berlin Wall separated West Berlin from East Berlin from 1961 to 1989.'),
('history', 1, 'Which civilization invented paper?', 'China', ARRAY['Egypt', 'Greece', 'Rome'], 'en', true, 'Paper was invented in China around 105 AD by Cai Lun.'),
('history', 1, 'Who painted the Mona Lisa?', 'Leonardo da Vinci', ARRAY['Michelangelo', 'Raphael', 'Botticelli'], 'en', true, 'Leonardo da Vinci painted the Mona Lisa around 1503-1519 in Florence.'),
('history', 1, 'Which pharaoh is famous for his golden death mask?', 'Tutankhamun', ARRAY['Ramesses II', 'Khufu', 'Akhenaten'], 'en', true, 'Tutankhamun''s golden death mask was discovered by Howard Carter in 1922.'),
('history', 1, 'What was Christopher Columbus''s flagship called?', 'The Santa Maria', ARRAY['The Mayflower', 'The Pinta', 'The Victoria'], 'en', true, 'The Santa Maria was Columbus''s flagship during his first voyage in 1492.'),
('history', 1, 'Who said "Veni, vidi, vici"?', 'Julius Caesar', ARRAY['Augustus', 'Alexander the Great', 'Napoleon'], 'en', true, 'Julius Caesar said "I came, I saw, I conquered" after his victory at Zela in 47 BC.'),
('history', 1, 'Which war was fought between the North and South of the United States?', 'The American Civil War', ARRAY['The War of Independence', 'The War of 1812', 'The Spanish-American War'], 'en', true, 'The American Civil War (1861-1865) was fought between Union and Confederate states.'),
('history', 1, 'Which explorer completed the first circumnavigation of the globe?', 'Magellan', ARRAY['Columbus', 'Vasco da Gama', 'James Cook'], 'en', true, 'Ferdinand Magellan started the first circumnavigation in 1519, completed by Elcano in 1522.'),
('history', 1, 'What monument was built for the 1889 World Fair in Paris?', 'The Eiffel Tower', ARRAY['The Arc de Triomphe', 'The Grand Palais', 'The Trocadero'], 'en', true, 'The Eiffel Tower was built by Gustave Eiffel for the 1889 Universal Exhibition.'),
('history', 1, 'Which empire dominated the Mediterranean 2,000 years ago?', 'The Roman Empire', ARRAY['The Greek Empire', 'The Persian Empire', 'The Carthaginian Empire'], 'en', true, 'The Roman Empire controlled the entire Mediterranean at its peak in the 2nd century.'),
('history', 1, 'Which English king had six wives?', 'Henry VIII', ARRAY['Henry V', 'Richard the Lionheart', 'Edward I'], 'en', true, 'Henry VIII had six wives and founded the Church of England.'),
('history', 1, 'What event ended World War II in the Pacific?', 'The atomic bombs on Hiroshima and Nagasaki', ARRAY['The Battle of Midway', 'Germany''s surrender', 'D-Day'], 'en', true, 'The atomic bombs dropped in August 1945 led to Japan''s surrender.'),
('history', 1, 'Which Asian people founded the largest contiguous land empire in history?', 'The Mongols', ARRAY['The Turks', 'The Persians', 'The Huns'], 'en', true, 'The Mongol Empire, founded by Genghis Khan, stretched from China to Eastern Europe.'),
('history', 1, 'What ancient civilization invented cuneiform writing?', 'The Sumerians', ARRAY['The Egyptians', 'The Greeks', 'The Chinese'], 'en', true, 'The Sumerians of Mesopotamia developed cuneiform writing around 3400 BC.'),
('history', 1, 'Which ship carried the first English colonists to America in 1620?', 'The Mayflower', ARRAY['The Santa Maria', 'The Titanic', 'The Victoria'], 'en', true, 'The Mayflower carried the Pilgrims from Plymouth, England to America in 1620.'),
('history', 1, 'What stone monument stands in Salisbury Plain, England?', 'Stonehenge', ARRAY['The Colosseum', 'The Parthenon', 'The Carnac stones'], 'en', true, 'Stonehenge is a megalithic monument built between 3000 and 2000 BC.'),
('history', 1, 'What was the title of ancient Egyptian rulers?', 'Pharaoh', ARRAY['Emperor', 'King', 'Sultan'], 'en', true, 'The pharaoh was considered a living god in ancient Egypt.'),
('history', 1, 'Which country built the Suez Canal?', 'France', ARRAY['England', 'Egypt', 'The Ottoman Empire'], 'en', true, 'The Suez Canal was built under French direction by Ferdinand de Lesseps, opening in 1869.'),
('history', 1, 'What invention allowed long-distance communication in the 19th century?', 'The telegraph', ARRAY['The telephone', 'The radio', 'Television'], 'en', true, 'The electric telegraph, developed by Samuel Morse in the 1830s, revolutionized communication.'),
('history', 1, 'Which scientist formulated the law of universal gravitation?', 'Isaac Newton', ARRAY['Galileo', 'Albert Einstein', 'Copernicus'], 'en', true, 'Newton published his law of universal gravitation in the Principia in 1687.'),
('history', 1, 'Which European country colonized India for centuries?', 'The United Kingdom', ARRAY['France', 'Portugal', 'Spain'], 'en', true, 'India was under British rule from 1858 to 1947.'),
('history', 1, 'What famous speech begins with "I have a dream"?', 'Martin Luther King''s speech', ARRAY['Kennedy''s speech', 'Lincoln''s speech', 'Mandela''s speech'], 'en', true, 'Martin Luther King delivered this speech on August 28, 1963 in Washington.'),
('history', 1, 'Which continent was discovered by Europeans in 1492?', 'The Americas', ARRAY['Australia', 'Antarctica', 'Africa'], 'en', true, 'Christopher Columbus reached the Americas in 1492 while searching for a route to India.'),
('history', 1, 'What is the name of the oldest written constitution still in use?', 'The US Constitution', ARRAY['The Magna Carta', 'The Declaration of Rights of Man', 'The Code of Hammurabi'], 'en', true, 'The US Constitution, ratified in 1788, is the oldest written constitution still in effect.'),
('history', 1, 'Which ancient people built the first Egyptian pyramids?', 'The Egyptians', ARRAY['The Romans', 'The Greeks', 'The Persians'], 'en', true, 'The first Egyptian pyramids date from around 2700 BC during the Old Kingdom.'),
('history', 1, 'What was the title of Japanese warrior elites?', 'Samurai', ARRAY['Monk', 'Merchant', 'Shogun'], 'en', true, 'Samurai were elite warriors of the Japanese military from the 12th to the 19th century.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 2, 'In what year did the Russian Revolution take place?', '1917', ARRAY['1905', '1914', '1921'], 'en', true, 'The Russian Revolution of 1917 overthrew Tsar Nicholas II and brought the Bolsheviks to power.'),
('history', 2, 'Which empire was the largest in history by land area?', 'The British Empire', ARRAY['The Mongol Empire', 'The Roman Empire', 'The Spanish Empire'], 'en', true, 'The British Empire covered about 35 million km2 at its peak in the 1920s.'),
('history', 2, 'Which Roman emperor built the wall in England?', 'Hadrian', ARRAY['Trajan', 'Augustus', 'Nero'], 'en', true, 'Hadrian''s Wall, built in 122 AD, marked the northern frontier of Roman Britain.'),
('history', 2, 'What event triggered the US entry into World War II?', 'The attack on Pearl Harbor', ARRAY['The London Blitz', 'The Battle of Stalingrad', 'The invasion of Poland'], 'en', true, 'The Japanese attack on Pearl Harbor on December 7, 1941 brought the US into the war.'),
('history', 2, 'Which queen reigned for 63 years in 19th century England?', 'Queen Victoria', ARRAY['Elizabeth I', 'Mary Stuart', 'Queen Anne'], 'en', true, 'Queen Victoria reigned from 1837 to 1901, giving her name to the Victorian era.'),
('history', 2, 'Which Asian country was closed to foreigners for over 200 years?', 'Japan', ARRAY['China', 'Korea', 'Vietnam'], 'en', true, 'Japan practiced sakoku (closed country) from 1639 to 1853 under the Tokugawa shogunate.'),
('history', 2, 'In what year was Nelson Mandela released from prison?', '1990', ARRAY['1988', '1994', '1985'], 'en', true, 'Nelson Mandela was released on February 11, 1990 after 27 years in prison.'),
('history', 2, 'What was the name of the English civil war between York and Lancaster?', 'The Wars of the Roses', ARRAY['The Hundred Years'' War', 'The English Civil War', 'The Barons'' War'], 'en', true, 'The Wars of the Roses (1455-1487) pitted the houses of York (white rose) and Lancaster (red rose).'),
('history', 2, 'Who led the Cuban Revolution in 1959?', 'Fidel Castro', ARRAY['Che Guevara', 'Raul Castro', 'Fulgencio Batista'], 'en', true, 'Fidel Castro overthrew dictator Batista and took power in Cuba in January 1959.'),
('history', 2, 'Which treaty created the European Union in 1992?', 'The Maastricht Treaty', ARRAY['The Treaty of Rome', 'The Treaty of Lisbon', 'The Treaty of Nice'], 'en', true, 'The Maastricht Treaty, signed in 1992, created the EU and paved the way for the euro.'),
('history', 2, 'What was the first crewed space mission to land on the Moon?', 'Apollo 11', ARRAY['Apollo 13', 'Gemini 4', 'Vostok 1'], 'en', true, 'Apollo 11 landed Neil Armstrong and Buzz Aldrin on the Moon on July 20, 1969.'),
('history', 2, 'Which country was the last in the Americas to abolish slavery in 1888?', 'Brazil', ARRAY['United States', 'Cuba', 'Haiti'], 'en', true, 'Brazil was the last country in the Americas to abolish slavery with the Golden Law in 1888.'),
('history', 2, 'What conflict opposed the US and USSR from 1947 to 1991?', 'The Cold War', ARRAY['The Vietnam War', 'The Korean War', 'The Arms Race'], 'en', true, 'The Cold War was a geopolitical and ideological conflict without direct military confrontation.'),
('history', 2, 'Which African empire was famous for its gold wealth in the 14th century?', 'The Mali Empire', ARRAY['The Songhai Empire', 'The Kingdom of Benin', 'The Ghana Empire'], 'en', true, 'Emperor Mansa Musa of Mali is considered the wealthiest person in history.'),
('history', 2, 'What fortified line did France build between the two world wars?', 'The Maginot Line', ARRAY['The Siegfried Line', 'The Atlantic Wall', 'The Hindenburg Line'], 'en', true, 'The Maginot Line, built in the 1930s, was designed to protect France from German invasion.'),
('history', 2, 'In what year did India gain independence?', '1947', ARRAY['1945', '1950', '1942'], 'en', true, 'India gained independence from the United Kingdom on August 15, 1947.'),
('history', 2, 'Who was the first emperor to unify China?', 'Qin Shi Huang', ARRAY['Confucius', 'Sun Tzu', 'Kublai Khan'], 'en', true, 'Qin Shi Huang unified China in 221 BC and began construction of the Great Wall.'),
('history', 2, 'Which international organization was created after WWII to maintain peace?', 'The United Nations', ARRAY['NATO', 'The League of Nations', 'UNESCO'], 'en', true, 'The United Nations was founded in 1945 with 51 member countries.'),
('history', 2, 'Which empire ruled Persia before Alexander the Great''s conquest?', 'The Achaemenid Empire', ARRAY['The Sassanid Empire', 'The Parthian Empire', 'The Seleucid Empire'], 'en', true, 'The Achaemenid Empire, founded by Cyrus the Great, ruled Persia from 550 to 330 BC.'),
('history', 2, 'What is the name of the doctrine prohibiting European interference in the Americas?', 'The Monroe Doctrine', ARRAY['The Truman Doctrine', 'The New Deal', 'The Marshall Plan'], 'en', true, 'The Monroe Doctrine, proclaimed in 1823, stated the Americas were closed to European colonization.'),
('history', 2, 'Which space program sent the first human into space?', 'Vostok', ARRAY['Mercury', 'Apollo', 'Gemini'], 'en', true, 'The Vostok program sent Yuri Gagarin into space on April 12, 1961.'),
('history', 2, 'What treaty ended the Thirty Years'' War?', 'The Peace of Westphalia', ARRAY['The Treaty of Versailles', 'The Treaty of Paris', 'The Treaty of Vienna'], 'en', true, 'The Peace of Westphalia in 1648 ended the Thirty Years'' War and reshaped Europe.'),
('history', 2, 'Which civilization built the city of Machu Picchu?', 'The Incas', ARRAY['The Aztecs', 'The Maya', 'The Olmecs'], 'en', true, 'Machu Picchu was built by the Incas in the 15th century at 2,430 m altitude in Peru.'),
('history', 2, 'What was Napoleon''s final defeat called?', 'The Battle of Waterloo', ARRAY['The Battle of Austerlitz', 'The Battle of Trafalgar', 'The Battle of Leipzig'], 'en', true, 'Napoleon was defeated at Waterloo on June 18, 1815, ending his rule.'),
('history', 2, 'Which artistic movement was born in Italy in the 14th century?', 'The Renaissance', ARRAY['The Baroque', 'The Enlightenment', 'Romanticism'], 'en', true, 'The Renaissance was born in Florence in the 14th century with artists like Giotto.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 3, 'What was the code name for the development of the atomic bomb?', 'The Manhattan Project', ARRAY['The Apollo Project', 'The Marshall Plan', 'Operation Overlord'], 'en', true, 'The Manhattan Project developed the first nuclear weapons between 1942 and 1946.'),
('history', 3, 'Which 1916 battle was the bloodiest of World War I?', 'The Battle of the Somme', ARRAY['The Battle of Verdun', 'The Battle of the Marne', 'The Battle of Gallipoli'], 'en', true, 'The Battle of the Somme caused over one million casualties between July and November 1916.'),
('history', 3, 'Who was the first person to perform a spacewalk?', 'Alexei Leonov', ARRAY['Yuri Gagarin', 'Neil Armstrong', 'Valentina Tereshkova'], 'en', true, 'Alexei Leonov performed the first spacewalk on March 18, 1965.'),
('history', 3, 'Which Roman emperor divided the empire into two parts?', 'Diocletian', ARRAY['Constantine', 'Theodosius', 'Augustus'], 'en', true, 'Diocletian established the tetrarchy in 293, dividing Roman administration.'),
('history', 3, 'Which 1945 conference redesigned Europe''s borders after the war?', 'The Yalta Conference', ARRAY['The Potsdam Conference', 'The Tehran Conference', 'The Casablanca Conference'], 'en', true, 'The Yalta Conference in February 1945 brought together Roosevelt, Churchill, and Stalin.'),
('history', 3, 'Which country launched the first space probe to land on Mars?', 'The USSR', ARRAY['The United States', 'Europe', 'China'], 'en', true, 'The Soviet Mars 3 probe was the first to soft-land on Mars in 1971.'),
('history', 3, 'Which siege lasted 872 days during World War II?', 'The Siege of Leningrad', ARRAY['The Siege of Stalingrad', 'The Siege of Berlin', 'The Siege of Warsaw'], 'en', true, 'The Siege of Leningrad lasted from September 8, 1941 to January 27, 1944.'),
('history', 3, 'What treaty established the European Economic Community in 1957?', 'The Treaty of Rome', ARRAY['The Maastricht Treaty', 'The Treaty of Versailles', 'The Treaty of Lisbon'], 'en', true, 'The Treaty of Rome, signed on March 25, 1957, founded the EEC with 6 member states.'),
('history', 3, 'What was Gorbachev''s reform policy in the USSR called?', 'Perestroika', ARRAY['Glasnost', 'Gulag', 'Detente'], 'en', true, 'Perestroika (restructuring) was Gorbachev''s program of economic and political reforms from 1985.'),
('history', 3, 'Which West African empire controlled trans-Saharan trade in the 15th century?', 'The Songhai Empire', ARRAY['The Mali Empire', 'The Ghana Empire', 'The Kingdom of Benin'], 'en', true, 'The Songhai Empire, with its capital Gao, dominated trans-Saharan trade in the 15th century.'),
('history', 3, 'In what year did apartheid officially end in South Africa?', '1991', ARRAY['1990', '1994', '1988'], 'en', true, 'Apartheid laws were repealed in 1991, followed by the first multiracial elections in 1994.'),
('history', 3, 'What was the code name for the D-Day invasion?', 'Operation Overlord', ARRAY['Operation Barbarossa', 'Operation Market Garden', 'Operation Torch'], 'en', true, 'Operation Overlord was the code name for the Allied invasion of Normandy on June 6, 1944.'),
('history', 3, 'Which country was the first to grant women the right to vote?', 'New Zealand', ARRAY['Finland', 'Norway', 'Australia'], 'en', true, 'New Zealand granted women the right to vote in 1893.'),
('history', 3, 'What crisis nearly triggered a nuclear war in 1962?', 'The Cuban Missile Crisis', ARRAY['The Berlin Crisis', 'The Suez Crisis', 'The Iran Hostage Crisis'], 'en', true, 'The Cuban Missile Crisis in October 1962 was the most dangerous moment of the Cold War.'),
('history', 3, 'Which Chinese dynasty built most of the Great Wall as it stands today?', 'The Ming Dynasty', ARRAY['The Qin Dynasty', 'The Han Dynasty', 'The Tang Dynasty'], 'en', true, 'Most of the Great Wall dates from the Ming Dynasty (1368-1644).'),
('history', 3, 'What German military doctrine of rapid warfare was used in 1940?', 'Blitzkrieg', ARRAY['Trench warfare', 'War of attrition', 'The Schlieffen Plan'], 'en', true, 'Blitzkrieg (lightning war) combined tanks, aircraft, and infantry for rapid attacks.'),
('history', 3, 'Which empire ruled India from the 16th to 19th century before the British?', 'The Mughal Empire', ARRAY['The Gupta Empire', 'The Maurya Empire', 'The Maratha Empire'], 'en', true, 'The Mughal Empire ruled much of India from 1526 to 1857 and built the Taj Mahal.'),
('history', 3, 'What 1989 event symbolizes the end of the Cold War?', 'The fall of the Berlin Wall', ARRAY['The dissolution of the USSR', 'German reunification', 'The Malta Summit'], 'en', true, 'The fall of the Berlin Wall on November 9, 1989 symbolizes the end of the Cold War.'),
('history', 3, 'Which scientist discovered the laws of genetics by studying peas?', 'Gregor Mendel', ARRAY['Charles Darwin', 'Louis Pasteur', 'Robert Koch'], 'en', true, 'Gregor Mendel discovered the laws of heredity studying pea plants in the 1860s.'),
('history', 3, 'What is the name of the ancient Babylonian code of laws carved on stone?', 'The Code of Hammurabi', ARRAY['The Twelve Tables', 'The Justinian Code', 'The Magna Carta'], 'en', true, 'The Code of Hammurabi, dating from about 1754 BC, is one of the oldest known written law codes.'),
('history', 3, 'What terrorist attack launched the War on Terror in 2001?', 'The September 11 attacks', ARRAY['The Madrid bombings', 'The London bombings', 'The Bali bombings'], 'en', true, 'The September 11, 2001 attacks in New York and Washington killed nearly 3,000 people.'),
('history', 3, 'Which Iranian revolution took place in 1979?', 'The Islamic Revolution', ARRAY['The White Revolution', 'The Carnation Revolution', 'The Green Revolution'], 'en', true, 'The 1979 Islamic Revolution overthrew the Shah and established an Islamic republic under Ayatollah Khomeini.'),
('history', 3, 'Which country was the first to industrialize textile production?', 'England', ARRAY['France', 'Germany', 'United States'], 'en', true, 'England was the birthplace of the Industrial Revolution with its cotton mills.'),
('history', 3, 'Who formulated the laws of planetary motion?', 'Johannes Kepler', ARRAY['Galileo', 'Copernicus', 'Newton'], 'en', true, 'Kepler formulated his three laws of planetary motion between 1609 and 1619.'),
('history', 3, 'What ancient Babylonian code preceded the Code of Hammurabi?', 'The Code of Ur-Nammu', ARRAY['The Twelve Tables', 'The Laws of Manu', 'The Hittite Laws'], 'en', true, 'The Code of Ur-Nammu dates from about 2100 BC, predating Hammurabi by 300 years.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 4, 'Who was the last Emperor of China?', 'Puyi', ARRAY['Kangxi', 'Qianlong', 'Cixi'], 'en', true, 'Puyi became emperor at age 2 in 1908 and abdicated in 1912.'),
('history', 4, 'Which 1571 naval battle stopped Ottoman expansion in the Mediterranean?', 'The Battle of Lepanto', ARRAY['The Battle of Trafalgar', 'The Battle of Salamis', 'The Battle of Actium'], 'en', true, 'The Battle of Lepanto in 1571 saw the Holy League defeat the Ottoman fleet.'),
('history', 4, 'Which 1494 treaty divided the New World between Spain and Portugal?', 'The Treaty of Tordesillas', ARRAY['The Treaty of Zaragoza', 'The Peace of Westphalia', 'The Treaty of Utrecht'], 'en', true, 'The Treaty of Tordesillas drew a line dividing newly discovered lands between Spain and Portugal.'),
('history', 4, 'Which Byzantine emperor codified Roman law?', 'Justinian', ARRAY['Constantine', 'Theodosius', 'Heraclius'], 'en', true, 'Justinian''s Corpus Juris Civilis, compiled between 529 and 534, is the foundation of civil law.'),
('history', 4, 'Which 1884-1885 conference organized the partition of Africa?', 'The Berlin Conference', ARRAY['The Vienna Conference', 'The Paris Conference', 'The London Conference'], 'en', true, 'The Berlin Conference established rules for European colonization and partition of Africa.'),
('history', 4, 'What ancient trade route connected China to the Mediterranean?', 'The Silk Road', ARRAY['The Spice Route', 'The Incense Route', 'The Amber Road'], 'en', true, 'The Silk Road stretched over 6,000 km, connecting Xi''an to Constantinople.'),
('history', 4, 'What was the name of the post-WWII European reconstruction plan?', 'The Marshall Plan', ARRAY['The Dawes Plan', 'The Schuman Plan', 'The Young Plan'], 'en', true, 'The Marshall Plan (1948-1952) provided $13 billion in US aid to rebuild Europe.'),
('history', 4, 'Which Japanese dynasty governed during the Edo period (1603-1868)?', 'The Tokugawa', ARRAY['The Ashikaga', 'The Fujiwara', 'The Minamoto'], 'en', true, 'The Tokugawa shogunate ruled Japan for over 250 years of relative peace.'),
('history', 4, 'What religious reform did Martin Luther launch in 1517?', 'The Protestant Reformation', ARRAY['The Counter-Reformation', 'The Great Schism', 'The Council of Trent'], 'en', true, 'Martin Luther launched the Reformation by posting his 95 theses in Wittenberg in 1517.'),
('history', 4, 'Which Carthaginian general used war elephants to cross the Alps?', 'Hannibal Barca', ARRAY['Hamilcar Barca', 'Hasdrubal', 'Scipio Africanus'], 'en', true, 'Hannibal crossed the Alps with about 37 war elephants in 218 BC.'),
('history', 4, 'What was the name of the German peasant revolt of 1524-1525?', 'The German Peasants'' War', ARRAY['The Jacquerie', 'The Ciompi Revolt', 'Wat Tyler''s Rebellion'], 'en', true, 'The German Peasants'' War was one of the largest popular uprisings of the 16th century.'),
('history', 4, 'Which treaty ended the Russo-Japanese War in 1905?', 'The Treaty of Portsmouth', ARRAY['The Treaty of Shimonoseki', 'The Treaty of San Stefano', 'The Treaty of Brest-Litovsk'], 'en', true, 'The Treaty of Portsmouth, brokered by Theodore Roosevelt, ended the Russo-Japanese War.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 5, 'What is the name of the first known civilization in Mesopotamia?', 'Sumer', ARRAY['Akkad', 'Babylon', 'Assyria'], 'en', true, 'Sumer, in southern Mesopotamia, is considered the first civilization around 4500 BC.'),
('history', 5, 'In what year did the Treaty of Nerchinsk set the border between Russia and China?', '1689', ARRAY['1721', '1654', '1725'], 'en', true, 'The Treaty of Nerchinsk in 1689 was the first treaty between Russia and China.'),
('history', 5, 'What is the name of the undeciphered writing system of the Indus Valley civilization?', 'The Indus script', ARRAY['Sanskrit', 'Cuneiform', 'Brahmi'], 'en', true, 'The Indus script remains undeciphered and dates from about 2600 BC.'),
('history', 5, 'Which Japanese admiral planned the attack on Pearl Harbor?', 'Isoroku Yamamoto', ARRAY['Hideki Tojo', 'Chuichi Nagumo', 'Takeo Kurita'], 'en', true, 'Admiral Yamamoto planned the Pearl Harbor attack despite his personal reservations.'),
('history', 5, 'What is the oldest known literary text in human history?', 'The Epic of Gilgamesh', ARRAY['The Iliad', 'The Bible', 'The Book of the Dead'], 'en', true, 'The Epic of Gilgamesh, dating from about 2100 BC, is the oldest known literary narrative.'),
('history', 5, 'Which Mughal emperor built the Taj Mahal?', 'Shah Jahan', ARRAY['Akbar', 'Aurangzeb', 'Babur'], 'en', true, 'Shah Jahan built the Taj Mahal between 1632 and 1653 in memory of his wife Mumtaz Mahal.'),
('history', 5, 'Which 1942 battle is considered the turning point of the war in the Pacific?', 'The Battle of Midway', ARRAY['The Battle of Guadalcanal', 'The Battle of Iwo Jima', 'The Battle of Leyte Gulf'], 'en', true, 'The Battle of Midway in June 1942 destroyed 4 Japanese aircraft carriers and reversed the war.'),
('history', 5, 'What was the name of the massive German peasant uprising inspired by Reformation ideas?', 'The German Peasants'' War of 1524', ARRAY['The Hussite Wars', 'The Anabaptist Revolt', 'The Schmalkaldic War'], 'en', true, 'The German Peasants'' War was Europe''s largest popular revolt before the French Revolution, involving 300,000 peasants.');
